<?php
require_once __DIR__.'/../config/config.php';
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/../includes/functions.php';
zorunlu_rol('admin','hakem');

$islem=$_GET['islem']??'liste'; $id=(int)($_GET['id']??0);
$formTur=$_GET['form_tur']??'lig_takim';
if(!in_array($formTur,['lig_takim','lig_bireysel','turnuva_takim','turnuva_bireysel'],true))$formTur='lig_takim';
$takimGruplari=$pdo->query("SELECT g.*,l.lig_adi FROM gruplar g JOIN ligler l ON l.id=g.lig_id WHERE l.tur='takim' ORDER BY l.lig_adi,g.grup_adi")->fetchAll();
$bireyselGruplar=$pdo->query("SELECT g.*,l.lig_adi FROM gruplar g JOIN ligler l ON l.id=g.lig_id WHERE l.tur='bireysel' ORDER BY l.lig_adi,g.bolge_adi,g.kategori_adi,g.grup_adi")->fetchAll();
$takimlar=$pdo->query("SELECT t.*,g.grup_adi FROM takimlar t JOIN gruplar g ON g.id=t.grup_id JOIN ligler l ON l.id=g.lig_id WHERE l.tur='takim' ORDER BY g.grup_adi,t.takim_adi")->fetchAll();
$hakemler=$pdo->query('SELECT * FROM hakemler ORDER BY ad,soyad')->fetchAll();

if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_check($_POST['csrf']??'')){flash_set('hata','Güvenlik doğrulaması başarısız.');redirect(BASE_URL.'/admin/maclar.php');}
 $postTur=$_POST['form_tur']??'lig_takim'; $geri=BASE_URL.'/admin/maclar.php?islem=ekle&form_tur='.urlencode($postTur);
 $tarih=$_POST['tarih']?:null; $saat=$_POST['saat']?:null; $yer=trim($_POST['yer']??'');
 if($postTur==='lig_takim'){
  $grupId=(int)($_POST['grup_id']??0);$ev=(int)($_POST['ev_sahibi_id']??0);$dep=(int)($_POST['deplasman_id']??0);$hafta=max(1,(int)($_POST['hafta']??1));$hakem=(int)($_POST['hakem_id']??0)?:null;$durum=$_POST['durum']??'planlandi';
  $k=$pdo->prepare("SELECT COUNT(*) FROM gruplar g JOIN ligler l ON l.id=g.lig_id WHERE g.id=? AND l.tur='takim'");$k->execute([$grupId]);
  $t=$pdo->prepare('SELECT COUNT(*) FROM takimlar WHERE grup_id=? AND id IN (?,?)');$t->execute([$grupId,$ev,$dep]);
  if(!$grupId||!$ev||!$dep||$ev===$dep||(int)$k->fetchColumn()!==1||(int)$t->fetchColumn()!==2){flash_set('hata','Takım Ligi için seçilen gruptan iki farklı takım seçin.');redirect($geri);}
  if(($_POST['islem']??'')==='duzenle'){$pdo->prepare('UPDATE maclar SET grup_id=?,ev_sahibi_id=?,deplasman_id=?,hafta=?,tarih=?,saat=?,yer=?,hakem_id=?,durum=? WHERE id=?')->execute([$grupId,$ev,$dep,$hafta,$tarih,$saat,$yer,$hakem,$durum,(int)$_POST['id']]);flash_set('basari','Takım Ligi maçı güncellendi.');}
  else {$pdo->prepare('INSERT INTO maclar(grup_id,ev_sahibi_id,deplasman_id,hafta,tarih,saat,yer,hakem_id,durum) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$grupId,$ev,$dep,$hafta,$tarih,$saat,$yer,$hakem,$durum]);flash_set('basari','Takım Ligi maçı eklendi.');}
 }elseif($postTur==='lig_bireysel'){
  $grupId=(int)($_POST['grup_id']??0);$k=$pdo->prepare("SELECT g.lig_id FROM gruplar g JOIN ligler l ON l.id=g.lig_id WHERE g.id=? AND l.tur='bireysel'");$k->execute([$grupId]);$g=$k->fetch();
  if(!$g||!$tarih||$yer===''){flash_set('hata','Bireysel Lig için grup, tarih ve atış yeri zorunludur.');redirect($geri);}
  $pdo->prepare('INSERT INTO bireysel_fikstur(lig_id,grup_id,tarih,saat,yer,aciklama) VALUES(?,?,?,?,?,?)')->execute([(int)$g['lig_id'],$grupId,$tarih,$saat,$yer,trim($_POST['aciklama']??'')?:null]);flash_set('basari','Bireysel Lig atış fikstürü eklendi.');
 }elseif(in_array($postTur,['turnuva_takim','turnuva_bireysel'],true)){
  $macId=(int)($_POST['turnuva_mac_id']??0);$tur=$postTur==='turnuva_takim'?'takim':'bireysel';$k=$pdo->prepare("SELECT tm.id FROM turnuva_maclari tm JOIN turnuvalar t ON t.id=tm.turnuva_id WHERE tm.id=? AND t.tur=? AND tm.katilimci1_id IS NOT NULL AND tm.katilimci2_id IS NOT NULL");$k->execute([$macId,$tur]);
  if(!$k->fetch()){flash_set('hata','Turnuva ağacında iki katılımcısı belli olan bir karşılaşma seçin.');redirect($geri);}
  $pdo->prepare('UPDATE turnuva_maclari SET tarih=?,saat=?,yer=? WHERE id=?')->execute([$tarih,$saat,$yer,$macId]);flash_set('basari','Turnuva karşılaşması planlandı.');
 }
 redirect(BASE_URL.'/admin/maclar.php');
}
if($islem==='sil'&&$id){$pdo->prepare('DELETE FROM maclar WHERE id=?')->execute([$id]);flash_set('basari','Maç silindi.');redirect(BASE_URL.'/admin/maclar.php');}
$duzenlenen=null;if($islem==='duzenle'&&$id){$q=$pdo->prepare('SELECT * FROM maclar WHERE id=?');$q->execute([$id]);$duzenlenen=$q->fetch();$formTur='lig_takim';}

$seciliTurnuvaMaclari=[];
if(in_array($formTur,['turnuva_takim','turnuva_bireysel'],true)){$tur=$formTur==='turnuva_takim'?'takim':'bireysel';$q=$pdo->prepare("SELECT tm.id,tm.tur_no,tr.turnuva_adi,CASE WHEN tr.tur='takim' THEN a.takim_adi ELSE CONCAT(sa.ad,' ',sa.soyad) END ev,CASE WHEN tr.tur='takim' THEN b.takim_adi ELSE CONCAT(sb.ad,' ',sb.soyad) END dep FROM turnuva_maclari tm JOIN turnuvalar tr ON tr.id=tm.turnuva_id LEFT JOIN takimlar a ON tr.tur='takim' AND a.id=tm.katilimci1_id LEFT JOIN takimlar b ON tr.tur='takim' AND b.id=tm.katilimci2_id LEFT JOIN sporcular sa ON tr.tur='bireysel' AND sa.id=tm.katilimci1_id LEFT JOIN sporcular sb ON tr.tur='bireysel' AND sb.id=tm.katilimci2_id WHERE tr.tur=? AND tm.katilimci1_id IS NOT NULL AND tm.katilimci2_id IS NOT NULL AND tm.durum='planlandi' ORDER BY tr.turnuva_adi,tm.tur_no,tm.id");$q->execute([$tur]);$seciliTurnuvaMaclari=$q->fetchAll();}

$kaynak=$_GET['kaynak']??'lig';if(!in_array($kaynak,['lig','turnuva'],true))$kaynak='lig';$ligTur=$_GET['lig_tur']??'takim';if(!in_array($ligTur,['takim','bireysel'],true))$ligTur='takim';$grupId=(int)($_GET['grup_id']??0);$turnuvaTur=$_GET['turnuva_tur']??'takim';if(!in_array($turnuvaTur,['takim','bireysel'],true))$turnuvaTur='takim';$durum=$_GET['durum']??'hepsi';if(!in_array($durum,['hepsi','planlandi','oynandi'],true))$durum='hepsi';
$q=$pdo->prepare('SELECT g.id,g.grup_adi FROM gruplar g JOIN ligler l ON l.id=g.lig_id WHERE l.tur=? ORDER BY g.grup_adi');$q->execute([$ligTur]);$filtreGruplar=$q->fetchAll();
if($kaynak==='lig'&&$ligTur==='takim'){$q=$pdo->prepare("SELECT m.*,t1.takim_adi ev,t2.takim_adi dep,g.grup_adi FROM maclar m JOIN takimlar t1 ON t1.id=m.ev_sahibi_id JOIN takimlar t2 ON t2.id=m.deplasman_id JOIN gruplar g ON g.id=m.grup_id WHERE (?=0 OR m.grup_id=?) AND (?='hepsi' OR m.durum=?) ORDER BY g.grup_adi,m.hafta,m.tarih");$q->execute([$grupId,$grupId,$durum,$durum]);$liste=$q->fetchAll();}
elseif($kaynak==='lig'){$q=$pdo->prepare('SELECT f.*,g.grup_adi FROM bireysel_fikstur f JOIN gruplar g ON g.id=f.grup_id WHERE (?=0 OR f.grup_id=?) ORDER BY f.tarih,f.saat');$q->execute([$grupId,$grupId]);$liste=$q->fetchAll();}
else{$q=$pdo->prepare("SELECT tm.*,tr.turnuva_adi grup_adi,CASE WHEN tr.tur='takim' THEN t1.takim_adi ELSE CONCAT(s1.ad,' ',s1.soyad) END ev,CASE WHEN tr.tur='takim' THEN t2.takim_adi ELSE CONCAT(s2.ad,' ',s2.soyad) END dep FROM turnuva_maclari tm JOIN turnuvalar tr ON tr.id=tm.turnuva_id LEFT JOIN takimlar t1 ON tr.tur='takim' AND t1.id=tm.katilimci1_id LEFT JOIN takimlar t2 ON tr.tur='takim' AND t2.id=tm.katilimci2_id LEFT JOIN sporcular s1 ON tr.tur='bireysel' AND s1.id=tm.katilimci1_id LEFT JOIN sporcular s2 ON tr.tur='bireysel' AND s2.id=tm.katilimci2_id WHERE tr.tur=? AND (?='hepsi' OR tm.durum=?) ORDER BY tr.turnuva_adi,tm.tur_no,tm.id");$q->execute([$turnuvaTur,$durum,$durum]);$liste=$q->fetchAll();}
ob_start();
?>
<?php if($islem==='ekle'||$islem==='duzenle'): ?>
<div class="toolbar"><a class="btn btn-outline" href="<?= BASE_URL ?>/admin/maclar.php">← Maçlara dön</a></div><div class="card"><div class="card-head"><h2><?= $islem==='duzenle'?'Takım Ligi Maçını Düzenle':'Yeni Karşılaşma / Atış Planı' ?></h2></div>
<?php if($islem==='ekle'): ?><form method="get" class="skor-filtre"><input type="hidden" name="islem" value="ekle"><label>Organizasyon türü<select name="form_tur" onchange="this.form.submit()"><option value="lig_takim" <?= $formTur==='lig_takim'?'selected':'' ?>>Takım Ligi</option><option value="lig_bireysel" <?= $formTur==='lig_bireysel'?'selected':'' ?>>Bireysel Bölge Ligleri</option><option value="turnuva_takim" <?= $formTur==='turnuva_takim'?'selected':'' ?>>Takım Turnuvası</option><option value="turnuva_bireysel" <?= $formTur==='turnuva_bireysel'?'selected':'' ?>>Bireysel Turnuva</option></select></label></form><?php endif; ?>
<form method="post" class="form"><?= csrf_field() ?><input type="hidden" name="islem" value="<?= e($islem) ?>"><input type="hidden" name="form_tur" value="<?= e($formTur) ?>"><?php if($duzenlenen): ?><input type="hidden" name="id" value="<?= (int)$duzenlenen['id'] ?>"><?php endif; ?>
<?php if($formTur==='lig_takim'): ?><div class="grid-2"><label>Grup *<select name="grup_id" id="macGrubu" required><option value="">Seçin</option><?php foreach($takimGruplari as $g): ?><option value="<?= (int)$g['id'] ?>" <?= $duzenlenen&&(int)$duzenlenen['grup_id']===(int)$g['id']?'selected':'' ?>><?= e($g['lig_adi'].' / '.$g['grup_adi']) ?></option><?php endforeach;?></select></label><label>Hafta *<input type="number" name="hafta" min="1" required value="<?= e($duzenlenen['hafta']??1) ?>"></label></div><div class="grid-2"><label>Ev sahibi *<select name="ev_sahibi_id" id="evTakimi" required><option value="">Seçin</option><?php foreach($takimlar as $t): ?><option value="<?= (int)$t['id'] ?>" data-grup="<?= (int)$t['grup_id'] ?>" <?= $duzenlenen&&(int)$duzenlenen['ev_sahibi_id']===(int)$t['id']?'selected':'' ?>><?= e($t['grup_adi'].' / '.$t['takim_adi']) ?></option><?php endforeach;?></select></label><label>Deplasman *<select name="deplasman_id" id="depTakimi" required><option value="">Seçin</option><?php foreach($takimlar as $t): ?><option value="<?= (int)$t['id'] ?>" data-grup="<?= (int)$t['grup_id'] ?>" <?= $duzenlenen&&(int)$duzenlenen['deplasman_id']===(int)$t['id']?'selected':'' ?>><?= e($t['grup_adi'].' / '.$t['takim_adi']) ?></option><?php endforeach;?></select></label></div>
<?php elseif($formTur==='lig_bireysel'): ?><p class="muted">Bireysel Bölge Liglerinde takım eşleşmesi yoktur; seçilen grubun kayıtlı sporcuları aynı atış planında yarışır.</p><label>Grup *<select name="grup_id" required><option value="">Seçin</option><?php foreach($bireyselGruplar as $g): ?><option value="<?= (int)$g['id'] ?>"><?= e($g['lig_adi'].' / '.($g['bolge_adi']?:$g['grup_adi']).' / '.($g['kategori_adi']?:'Kategori')) ?></option><?php endforeach;?></select></label><label>Açıklama<input name="aciklama" placeholder="Örn. 1. ayak atışı"></label>
<?php else: ?><p class="muted">Turnuva eşleşmeleri turnuva ağacıyla otomatik oluşur. Buradan katılımcısı belli karşılaşmanın tarih, saat ve yerini planlayın.</p><label>Turnuva karşılaşması *<select name="turnuva_mac_id" required><option value="">Seçin</option><?php foreach($seciliTurnuvaMaclari as $m): ?><option value="<?= (int)$m['id'] ?>"><?= e($m['turnuva_adi'].' · '.$m['tur_no'].'. tur · '.$m['ev'].' — '.$m['dep']) ?></option><?php endforeach;?></select></label><?php if(!$seciliTurnuvaMaclari): ?><p class="muted">Planlanabilir karşılaşma yok. Önce turnuva katılımcılarını ve eşleşmelerini oluşturun.</p><?php endif; ?><?php endif; ?>
<div class="grid-3"><label>Tarih<?= $formTur==='lig_bireysel'?' *':'' ?><input type="date" name="tarih" <?= $formTur==='lig_bireysel'?'required':'' ?> value="<?= e($duzenlenen['tarih']??'') ?>"></label><label>Saat<input type="time" name="saat" value="<?= e($duzenlenen['saat']??'') ?>"></label><?php if($formTur==='lig_takim'): ?><label>Hakem<select name="hakem_id"><option value="">— Atanmadı —</option><?php foreach($hakemler as $h): ?><option value="<?= (int)$h['id'] ?>" <?= $duzenlenen&&(int)$duzenlenen['hakem_id']===(int)$h['id']?'selected':'' ?>><?= e($h['ad'].' '.$h['soyad']) ?></option><?php endforeach;?></select></label><?php endif;?></div><div class="grid-2"><label>Yer<?= $formTur==='lig_bireysel'?' *':'' ?><input name="yer" <?= $formTur==='lig_bireysel'?'required':'' ?> value="<?= e($duzenlenen['yer']??'') ?>"></label><?php if($formTur==='lig_takim'): ?><label>Durum<select name="durum"><option value="planlandi">Planlandı</option><option value="oynandi" <?= ($duzenlenen['durum']??'')==='oynandi'?'selected':'' ?>>Oynandı</option><option value="iptal" <?= ($duzenlenen['durum']??'')==='iptal'?'selected':'' ?>>İptal</option></select></label><?php endif;?></div><div class="form-actions"><button class="btn btn-primary" <?= in_array($formTur,['turnuva_takim','turnuva_bireysel'],true)&&!$seciliTurnuvaMaclari?'disabled':'' ?>><?= $islem==='duzenle'?'Güncelle':'Kaydet' ?></button><a href="<?= BASE_URL ?>/admin/maclar.php" class="btn btn-outline">İptal</a></div></form></div>
<?php if($formTur==='lig_takim'): ?><script>(()=>{const g=document.getElementById('macGrubu'),s=[document.getElementById('evTakimi'),document.getElementById('depTakimi')];function f(){s.forEach(x=>{[...x.options].forEach(o=>{if(!o.value)return;let ok=!g.value||o.dataset.grup===g.value;o.hidden=!ok;o.disabled=!ok});if(x.selectedOptions[0]?.disabled)x.value=''})}g.addEventListener('change',f);f()})()</script><?php endif; ?>
<?php else: ?><form method="get" class="skor-filtre"><label>Kaynak<select name="kaynak" onchange="this.form.submit()"><option value="lig" <?= $kaynak==='lig'?'selected':'' ?>>Lig Karşılaşmaları</option><option value="turnuva" <?= $kaynak==='turnuva'?'selected':'' ?>>Turnuvalar</option></select></label><?php if($kaynak==='lig'): ?><label>Lig türü<select name="lig_tur" onchange="this.form.submit()"><option value="takim" <?= $ligTur==='takim'?'selected':'' ?>>Takım Ligi</option><option value="bireysel" <?= $ligTur==='bireysel'?'selected':'' ?>>Bireysel Bölge Ligleri</option></select></label><label>Grup<select name="grup_id" onchange="this.form.submit()"><option value="0">Tüm gruplar</option><?php foreach($filtreGruplar as $g): ?><option value="<?= (int)$g['id'] ?>" <?= $grupId===(int)$g['id']?'selected':'' ?>><?= e($g['grup_adi']) ?></option><?php endforeach;?></select></label><?php else: ?><label>Turnuva türü<select name="turnuva_tur" onchange="this.form.submit()"><option value="takim" <?= $turnuvaTur==='takim'?'selected':'' ?>>Takım Turnuvası</option><option value="bireysel" <?= $turnuvaTur==='bireysel'?'selected':'' ?>>Bireysel Turnuva</option></select></label><?php endif;?><label>Durum<select name="durum" onchange="this.form.submit()"><option value="hepsi">Tümü</option><option value="planlandi" <?= $durum==='planlandi'?'selected':'' ?>>Planlanan</option><option value="oynandi" <?= $durum==='oynandi'?'selected':'' ?>>Tamamlanan</option></select></label></form><div class="toolbar"><a href="?islem=ekle" class="btn btn-primary">+ Yeni Karşılaşma / Atış Planı</a><a href="<?= BASE_URL ?>/admin/gruplar.php" class="btn btn-outline">Fikstür Oluştur (Gruplar)</a><a href="<?= BASE_URL ?>/admin/mac-skor.php" class="btn btn-primary">Skor Girişi →</a></div><div class="table-wrap"><table class="data-table"><thead><tr><?php if($kaynak==='lig'&&$ligTur==='bireysel'): ?><th>Grup</th><th>Tarih</th><th>Saat</th><th>Yer</th><th>Açıklama</th><?php else: ?><th>Organizasyon</th><th>Tur / Hafta</th><th>Tarih</th><th>Ev</th><th>Skor</th><th>Deplasman</th><th>Yer</th><th>Durum</th><th></th><?php endif;?></tr></thead><tbody><?php foreach($liste as $m): ?><?php if($kaynak==='lig'&&$ligTur==='bireysel'): ?><tr><td><?= e($m['grup_adi']) ?></td><td><?= tr_tarih($m['tarih']) ?></td><td><?= tr_saat($m['saat']) ?></td><td><?= e($m['yer']) ?></td><td><?= e($m['aciklama']?:'—') ?></td></tr><?php else: ?><tr><td><?= e($m['grup_adi']) ?></td><td><?= $kaynak==='turnuva'?(int)$m['tur_no'].'. Tur':(int)$m['hafta'] ?></td><td><?= tr_tarih($m['tarih']) ?> <?= tr_saat($m['saat']) ?></td><td><?= e($m['ev']?:'—') ?></td><td><?= $kaynak==='turnuva'?(int)$m['puan1'].' - '.(int)$m['puan2']:($m['durum']==='oynandi'?(int)$m['ev_sahibi_set'].' - '.(int)$m['deplasman_set']:'vs') ?></td><td><?= e($m['dep']?:'—') ?></td><td><?= e($m['yer']?:'—') ?></td><td><?= e($m['durum']) ?></td><td><?php if($kaynak==='turnuva'): ?><a href="<?= BASE_URL ?>/admin/turnuva-skor.php?id=<?= (int)$m['id'] ?>" class="btn btn-sm btn-primary">Skor Gir</a><?php else: ?><a href="<?= BASE_URL ?>/admin/mac-skor.php?mac_id=<?= (int)$m['id'] ?>" class="btn btn-sm btn-primary">Skor</a><a href="?islem=duzenle&id=<?= (int)$m['id'] ?>" class="btn btn-sm">Düzenle</a><a href="?islem=sil&id=<?= (int)$m['id'] ?>" class="btn btn-sm btn-danger" onclick="return confirm('Silinsin mi?')">Sil</a><?php endif;?></td></tr><?php endif;?><?php endforeach;?></tbody></table></div><?php endif;?>
<?php $admin_baslik='Maçlar';$admin_aktif='maclar';$admin_icerik=ob_get_clean();require __DIR__.'/partials/layout.php';
